import '../../models/dcc/dcc_master_data.dart';
import 'dcc_api_client.dart';
class DccMasterDataService {
 static const String tableName='dcc_master_data';
 static Map<String,dynamic> _toRow(DccMasterData e)=>{'document_no':e.documentNo,'document_name':e.documentName,'document_type':e.documentType,'department':e.department,'candidate_name':e.candidateName,'candidate_email':e.candidateEmail,'created_by_name':e.createdByName,'created_by_email':e.createdByEmail,'revision':e.revision,'updated_at':DateTime.now().toIso8601String()};
 static DccMasterData _from(dynamic r){final m=Map<String,dynamic>.from(r as Map);return DccMasterData(documentNo:m['document_no']?.toString()??'',documentName:m['document_name']?.toString()??'',documentType:m['document_type']?.toString()??'',department:m['department']?.toString()??'',candidateName:m['candidate_name']?.toString()??'',candidateEmail:m['candidate_email']?.toString()??'',createdByName:m['created_by_name']?.toString()??'',createdByEmail:m['created_by_email']?.toString()??'',revision:int.tryParse(m['revision']?.toString()??'')??0);}
 static Future<void> upsertEntry(DccMasterData entry,{int? manualRevision}) async {final no=entry.documentNo.trim();if(no.isEmpty)throw Exception('Document No is required.');final existing=await getByDocumentNo(no);final rev=manualRevision??((existing?.revision??-1)+1);final resolved=DccMasterData(documentNo:no,documentName:entry.documentName,documentType:entry.documentType,department:entry.department,candidateName:entry.candidateName,candidateEmail:entry.candidateEmail,createdByName:entry.createdByName,createdByEmail:entry.createdByEmail,revision:rev<0?0:rev);await DccApiClient.post('/master-data/upsert',body:{'data':_toRow(resolved)});}
 static Future<List<DccMasterData>> getAllEntries() async => (await DccApiClient.get('/master-data') as List).map(_from).toList();
 static Future<DccMasterData?> getByDocumentNo(String documentNo) async {final n=documentNo.trim();if(n.isEmpty)return null;try{return _from(await DccApiClient.get('/master-data/${Uri.encodeComponent(n)}'));}catch(_){return null;}}
 static Future<void> deleteEntry(String documentNo) async=>DccApiClient.delete('/master-data/${Uri.encodeComponent(documentNo.trim())}');
}
